import fs from 'node:fs';
import { BRAND_LEXICON, normalizeBrandKey } from '../src/lexicon/brands.js';
const root=new URL('../',import.meta.url);
const seeds=fs.readFileSync(new URL('data/knowledge/brand-seeds.txt',root),'utf8').split(/\r?\n/)
  .filter(s=>s.trim()&&!s.trim().startsWith('#')).map(s=>s.replace(/^\uFEFF/,'').split('|'));
// Only the pre-existing curated vocabulary participates in identity choice;
// rebuilding with a prior generated file must produce identical ids.
const original=BRAND_LEXICON.filter(b=>!b.id.startsWith('archive-'));
const key=s=>normalizeBrandKey(s)?.replaceAll(' ','');
const byKey=new Map(original.flatMap(b=>b.aliases.map(a=>[key(a),b])));
const added=[],aliases={},collisions=[];
const typedOnly=new Set(['belgian','minis','star','city','original','extra','apple','farm','flow','noor','clear','fa','hayat','arrow','junior','novel','bibi','fem','relax','smile','tara','eva','basics','universal','oscar','royalprince','golden','royalford','hmd','hp','lg','ski','dac','omo','rex','sunny']);
for(const [en,ar,...variants] of seeds){
  const existing=byKey.get(key(en))||byKey.get(key(ar));
  const id=existing?.id||'archive-'+key(en).replace(/[^a-z0-9]/g,'');
  if(!existing){
    const entry={id,display_en:en,display_ar:ar,aliases:[en,ar]};
    added.push({slug:id,en,ar,archive:true,typedOnly:typedOnly.has(key(en))});
    byKey.set(key(en),entry);byKey.set(key(ar),entry);
  }
  aliases[id]||=[];
  for(const value of [en,ar,...variants]){
    const previous=byKey.get(key(value));
    if(previous&&previous.id!==id){collisions.push({value,id,previous:previous.id});continue;}
    aliases[id].push(value);byKey.set(key(value),{id});
  }
}
if(collisions.length)throw Error(JSON.stringify(collisions));
fs.mkdirSync(new URL('src/knowledge/',root),{recursive:true});
fs.writeFileSync(new URL('src/knowledge/archiveBrands.js',root),
  '// Generated by scripts/compile-archive-brands.mjs from reviewed archive brand seeds.\n'+
  'export const ARCHIVE_BRANDS = '+JSON.stringify(added,null,2)+';\n'+
  'export const ARCHIVE_BRAND_ALIASES = '+JSON.stringify(aliases,null,2)+';\n');
console.log(JSON.stringify({reviewedSeedRows:seeds.length,added:added.length,aliasGroups:Object.keys(aliases).length}));
